_var_0119 = 240
# ==== V229b DecemLineage：按 DECEM 四个提交 396 局录像人工总结的"买什么、哪天买"日程 ====
# 结构与 LineageOpening 相同：固定日历 + 按当天已开商店数量的公式算动物/作物目标，
# 执行层(路线/喂养/收获)沿用 LineageOpening。0-239 步用本模块，240 步起交给 round_controller。
#
# 日历（396 局中位数/多数）：
#   d0  2牛 3羊，6甜瓜，13小麦(当饲料+腾地)，雇4人
#   d1  甜瓜→7，雇3人
#   d2  攒化肥钱，约8点买第3头牛；第1株草莓；甜瓜→9；雇6人；开始收2-4日龄小麦喂牲口
#   d3-5 第一家店：纱线店→每天+1羊(3→4→5)，否则每天+1牛(3→4→5，奶店再多)；草莓补到约7
#   d6  用第一批羊毛钱买东北地；按商店：牛/羊/鹅/草莓一大波；雇9人
#   d8  买西南地(82%)，否则d9；开始番茄、小麦大田、宠物店时种胡萝卜；雇9人
#   d9  第三家店后再补动物/番茄/小麦；雇10人。d10 起(第4块地等)由后端决定。
# 当天市场顺序：饲料麦 → 雇工 → 买地 → 动物(羊/牛/鹅) → 草莓/甜瓜/番茄种子 → 小麦/胡萝卜种子；
#   动物目标没买齐时，上午(≤10点)不花钱买作物种子(DECEM 第2天攒到8点买牛)。
import sys as _s2
_LOM2 = _s2.modules['_gold_1ff5f6975590_lineage_opening']
_DL_CFG = dict(order=True, save_hour=10, early_wheat=True, crew=True, land=True, own_feed=False, d0_melon=6, sell_wheat=False, water_wheat=False)
_DL_CFG.update({"crew_floor_only":False,"d0_melon":5,"sell_wheat":True,"water_wheat":True,"replan":[16,19],"nofeed_new":True})
_DL_MILK = ('PIZZA_SHOP', 'ICE_CREAM_SHOP', 'SMOOTHIE_SHOP'); _DL_EGG = ('BAKERY', 'BRUNCH_SPOT')
_DL_STR = ('BRUNCH_SPOT', 'ICE_CREAM_SHOP', 'SMOOTHIE_SHOP', 'FARMERS_MARKET'); _DL_TOM = ('PIZZA_SHOP', 'FARMERS_MARKET')

def _dl_feat(shops):
    return dict(m=sum(s in _DL_MILK for s in shops), y=shops.count('YARN_STORE'), e=sum(s in _DL_EGG for s in shops),
                s=sum(s in _DL_STR for s in shops), t=sum(s in _DL_TOM for s in shops), p=shops.count('PET_CAFE'))

# 公式：目标 = 常数 + Σ 系数×(当天已知的该类商店数)；m奶店 y纱线店 e蛋店(面包/早午餐) s草莓店 t番茄店 p宠物店
# 数值来自 396 局线性回归(第二天开始时的地块/动物数)，保留一位小数；负数取 0。
_DL_TABLE = {
    0: dict(COW=(2,), SHEEP=(3,), GOOSE=(0,), MELON=(6,), WHEAT=(13,)),
    1: dict(COW=(2,), SHEEP=(3,), GOOSE=(0,), MELON=(7,), WHEAT=(13,)),
    2: dict(COW=(3,), SHEEP=(3,), GOOSE=(0,), MELON=(9,), STRAWBERRY=(1,)),
    3: dict(COW=(3.9, {'y': -0.9}), SHEEP=(3.0, {'y': 1.0}), GOOSE=(0.0,), STRAWBERRY=(5.2, {'m': -1.1, 'y': -2.5, 'e': -1.0, 't': -0.8, 'p': -1.2}), MELON=(9.7, {'y': 0.7, 'p': 0.4})),
    4: dict(COW=(4.8, {'m': 0.8, 'y': -1.8}), SHEEP=(3.0, {'y': 2.0}), GOOSE=(0.1,), STRAWBERRY=(7.3, {'m': -2.3, 'y': -2.5, 'e': -0.8, 's': 0.7, 't': -0.6, 'p': -1.0}), MELON=(9.7, {'y': 0.7, 'p': 0.5})),
    5: dict(COW=(4.3, {'m': 1.4, 'y': -1.3, 'e': 0.7, 't': 0.7, 'p': 0.7}), SHEEP=(3.0, {'y': 2.7}), GOOSE=(0.1,), STRAWBERRY=(8.0, {'m': -1.7, 'y': -2.5, 'e': -1.0, 's': 0.3, 't': -0.9, 'p': -1.2}), MELON=(9.7, {'y': 0.7, 'p': 0.5})),
    6: dict(COW=(4.0, {'m': 2.8, 'y': -1.0, 'e': 0.5, 't': 0.7, 'p': 0.6}), SHEEP=(3.1, {'y': 5.8}), GOOSE=(8.8, {'m': -2.8, 'y': -5.7, 'e': -0.5, 's': -2.0, 't': -0.8, 'p': -1.0}), STRAWBERRY=(16.0, {'m': -1.0, 'y': -3.7, 'e': -0.6, 's': 7.1, 't': -0.3}), MELON=(11.7, {'e': 0.3, 's': -0.8, 'p': 0.6}), WHEAT=(4.8, {'m': 0.7, 'y': 1.5, 's': -3.3, 't': 0.4})),
    7: dict(COW=(3.8, {'m': 3.0, 'y': -0.8, 'e': 0.5, 't': 0.7, 'p': 0.7}), SHEEP=(3.1, {'y': 6.0}), GOOSE=(8.9, {'m': -2.8, 'y': -5.5, 'e': -0.4, 's': -2.1, 't': -0.8, 'p': -1.0}), STRAWBERRY=(16.1, {'m': -0.8, 'y': -2.7, 'e': -0.8, 's': 7.2, 't': -0.5}), MELON=(11.8, {'s': -0.8, 'p': 0.6}), WHEAT=(6.2, {'m': 0.7, 'y': 2.7, 's': -4.1, 't': 0.4})),
    8: dict(COW=(4.5, {'m': 3.1, 'y': -1.2, 't': 0.3}), SHEEP=(3.1, {'y': 6.9}), GOOSE=(9.6, {'m': -2.4, 'y': -6.1, 's': -2.0, 't': -0.4, 'p': -0.4}), STRAWBERRY=(16.1, {'m': -0.7, 'y': -2.9, 'e': -1.0, 's': 8.2, 't': -0.9, 'p': -0.5}), MELON=(12.2, {'y': -0.4}), WHEAT=(16.6, {'m': 0.8, 'y': -6.6, 'e': 1.2, 's': -3.5, 't': 0.9}), TOMATO=(4.6, {'y': -3.1, 's': -2.2, 't': 1.5}), CARROT=(-0.1, {'p': 1.7})),
    9: dict(COW=(5.2, {'m': 2.8, 'y': -0.7}), SHEEP=(2.9, {'y': 6.0}), GOOSE=(10.9, {'m': -2.3, 'y': -3.9, 'e': 0.8, 's': -1.1}), STRAWBERRY=(17.4, {'m': -0.4, 'y': -1.5, 'e': -1.4, 's': 6.1, 't': -1.2, 'p': -1.2}), MELON=(12.2,), WHEAT=(23.1, {'m': -0.8, 'y': -1.0, 's': -3.1, 't': -0.9, 'p': -1.4}), TOMATO=(4.8, {'m': 0.3, 'e': 0.5, 's': -2.0, 't': 2.1}), CARROT=(-1.7, {'y': 0.4, 'e': 0.5, 'p': 2.3})),
}
_DL_CREW = {0: 4, 1: 3, 2: 5, 3: 6, 6: 9, 7: 8, 8: 9, 9: 10}   # 每天雇工（DECEM 482局中位数）
_DL_LAND = {2: 6, 3: 8}                                    # 第2块地第6天，第3块地第8天（没钱则顺延）

def _dl_eval(day, key, shops):
    row = _DL_TABLE.get(min(day, 9), {})
    if key not in row:
        return None
    spec = row[key]
    v = spec[0]
    if len(spec) > 1:
        f = _dl_feat(shops)
        v += sum(c * f[k] for k, c in spec[1].items())
    return max(0, int(round(v)))

class DecemLineage(_LOM2.LineageOpening):
    decem_order = True
    decem_goose_day = 9      # DECEM 开局天天喂、照料鹅（原 Lineage 隔天喂鹅、不照料）

    def herd_target(self, obs, day):
        if day > 9:
            return super().herd_target(obs, day)
        shops = list(obs['town']['unlocked_shops'])
        t = {a: _dl_eval(day, a, shops) for a in ('COW', 'SHEEP', 'GOOSE')}
        # 目标只增不减（DECEM 开局从不卖动物）
        prev = getattr(self, '_dl_prev_herd', {})
        for a in t:
            t[a] = max(t[a] or 0, prev.get(a, 0))
        self._dl_prev_herd = dict(t)
        return t

    def crop_targets(self, day):
        if day > 9:
            return super().crop_targets(day)
        shops = self._shops
        t = {}
        for crop in ('STRAWBERRY', 'MELON', 'WHEAT', 'TOMATO', 'CARROT'):
            v = _dl_eval(day, crop, shops)
            t[crop] = v if v is not None else 0
        if day == 0:
            t['MELON'] = min(t['MELON'], int(_DL_CFG['d0_melon']))
        if day in (2, 3, 4, 5):
            t['WHEAT'] = 0          # 第0天的小麦收完就不补种，腾地给草莓/动物
        return t

    def crop_controls(self, pos, tile, day):
        if tile.get('crop') == 'WHEAT' and pos in getattr(self, '_dl_early', ()):
            age = day - tile['planted_day']
            # 先浇水(2-4日龄浇水当场+1产量)再收
            return dict(fertilize_ages=set(), water_ages={age} if age >= 2 else set(), harvest_ages=set(), end_age=age)
        if _DL_CFG['water_wheat'] and tile.get('crop') == 'WHEAT' and day <= 6:
            # 第0天的小麦：1日龄起每天浇水(涨产)，到4日龄收
            age = day - tile['planted_day']
            return dict(fertilize_ages=set(), water_ages={age} if age >= 2 else set(), harvest_ages=set(), end_age=4)
        return super().crop_controls(pos, tile, day)

    def _dl_plan_early(self, obs, day):
        # DECEM 第2-4天把2-4日龄的小麦分批收掉：一是当天饲料，二是给草莓/新动物腾地
        self._dl_early = set()
        if not _DL_CFG['early_wheat'] or day > 6:
            return
        farm = obs['farms'][obs['player']]
        quads = ('NW', 'NE', 'SW', 'SE')[:len(farm['unlocked_quadrants'])]
        free = 0; cnt = {}; wheat = []; herd = {}
        for y in range(10):
            for x in range(10):
                q = ('N' if y < 5 else 'S') + ('W' if x < 5 else 'E')
                if q not in quads: continue
                t = farm['tiles'][y][x]
                if t is None or (isinstance(t, dict) and t.get('kind') == 'WEED'):
                    free += 1
                elif isinstance(t, dict) and t.get('kind') == 'PLANT':
                    cnt[t['crop']] = cnt.get(t['crop'], 0) + 1
                    age = day - t['planted_day']
                    if t['crop'] == 'WHEAT':
                        if age >= 4: free += 1
                        elif age >= 2: wheat.append((-age, -(abs(x - 4.5) + abs(y - 4.5)), (x, y)))
                elif isinstance(t, dict) and t.get('animal'):
                    herd[t['animal']] = herd.get(t['animal'], 0) + 1
        tg = self.crop_targets(day); ht = self.herd_target(obs, day)
        need = sum(max(0, tg.get(c, 0) - cnt.get(c, 0)) for c in ('STRAWBERRY', 'MELON', 'TOMATO'))
        need += sum(max(0, ht[a] - herd.get(a, 0) - obs['private']['shed'].get(a, 0)) for a in ht)
        k = max(0, need - free)
        order = sorted(wheat)
        for _, _, pos in order[:k]:
            self._dl_early.add(pos)
        if _DL_CFG['own_feed'] and 2 <= day <= 5:
            # 当天饲料用自己田里的麦：收到够喂全部牲口为止
            have = obs['private']['shed'].get('WHEAT', 0) + sum(inv.get('WHEAT', 0) for inv in obs['private']['inventories'])
            herd_n = sum(herd.values()) + sum(obs['private']['shed'].get(a, 0) for a in ('COW', 'SHEEP', 'GOOSE'))
            got = 0
            for _, _, pos in order:
                if pos in self._dl_early:
                    got += max(1, farm['tiles'][pos[1]][pos[0]].get('yield_units', 0))
            for _, _, pos in order:
                if have + got >= herd_n: break
                if pos not in self._dl_early:
                    self._dl_early.add(pos); got += max(1, farm['tiles'][pos[1]][pos[0]].get('yield_units', 0))
            self._dl_feed_ok = have + got >= herd_n

    def choose_crew(self, obs):
        super().choose_crew(obs)
        self._dl_dyn = self.crew

    def build(self, obs):
        self._dl_dyn = 0
        super().build(obs)
        # DECEM 的雇工数是它自己路线效率下的数；我们的执行层按作业量需要更多人时不压低(防止漏喂)
        if self.day <= 9 and _DL_CFG.get('crew_floor_only', True):
            self.crew = max(self.crew, min(int(self.p['crew_cap']), getattr(self, '_dl_dyn', 0)))

    def cash_reserve(self, prices):
        base = super().cash_reserve(prices)
        if 6 <= self.day <= 9 and _DL_CFG.get('full_feed', True):
            # 给明天留足全部饲料钱（不是一半），牲口多时防止第二天买不起麦漏喂
            crew_next = _LOM2._fn_0170(_LOM2.CREW, self.day + 1, 4)
            return _LOM2.fibcost(crew_next) + self.herd_count * (prices['WHEAT'] + 2) + 20
        return base

    def market(self, obs, hour, unit_actions=None):
        orders = super().market(obs, hour, unit_actions)
        day = int(obs['step']) // 24
        if _DL_CFG['sell_wheat'] and 2 <= day <= 7 and hour >= 1:
            # DECEM 把自家收的小麦留够明天的饲料，其余当天卖掉
            private = obs['private']
            have = private['shed'].get('WHEAT', 0)
            sold = sum(int(o[2]) for o in orders if o[0] == 'SELL' and o[1] == 'WHEAT')
            bought = any(o[0] == 'BUY_PRODUCT' and o[1] == 'WHEAT' for o in orders)
            keep_w = self.herd_count + 2
            extra = have - sold - keep_w
            if extra > 0 and not bought and len(orders) < 10:
                orders = [['SELL', 'WHEAT', extra]] + orders
        if _DL_CFG['own_feed'] and 2 <= day <= 5 and getattr(self, '_dl_feed_ok', False) and orders:
            orders = [o for o in orders if not (o[0] == 'BUY_PRODUCT' and o[1] == 'WHEAT')]
        return orders

    def begin_day(self, obs):
        day = int(obs['step']) // 24
        self._dl_feed_ok = False
        self._shops = list(obs['town']['unlocked_shops'])
        if day <= 9:
            if _DL_CFG['crew']:
                for k in list(_LOM2.CREW):
                    if k <= 10: _LOM2.CREW.pop(k, None)
                _LOM2.CREW.update(_DL_CREW)
                # 买地当天(第6、8天)我们的路线效率不如DECEM，按配置多雇人把种植当天做完
                for dd, extra in (_DL_CFG.get('land_extra') or {}).items():
                    _LOM2.CREW[int(dd)] = _DL_CREW.get(int(dd), 9) + int(extra)
                    _LOM2.CREW.setdefault(int(dd) + 1, _DL_CREW.get(int(dd) + 1, 9))
            if _DL_CFG['land']:
                self.p['unlock_ne'], self.p['unlock_sw'], self.p['unlock_se'] = _DL_LAND[2], _DL_LAND[3], 99
            if day == 0:
                self.p['initial_buffer'] = 0
            self.decem_order = bool(_DL_CFG['order'])
            # 新放的动物当天不喂不照料（当天不会逃；首产前照料加成本来就会超出上限，不损失产量）
            self.decem_nofeed_new = bool(_DL_CFG.get('nofeed_new', False))
            # 买到新种子后允许重排路线到更晚（DECEM 第6天草莓种到20点、第8天小麦种到22点）
            self.decem_replan = tuple(_DL_CFG.get('replan', (8, 14)))
            self.decem_save_hour = int(_DL_CFG['save_hour'])
            self._dl_plan_early(obs, day)
        else:
            self.decem_order = False
            self.decem_replan = None
            self.decem_nofeed_new = False
            self._dl_early = set()
        super().begin_day(obs)

_LOM2.LAST_PLANT['MELON'] = 8
if _DL_CFG.get('crew_exact', False):
    _LOM2._var_0157.add('crew_exact')   # 开局雇工严格按 DECEM 日程（不临时加人）
_LOM2.LineageOpening = DecemLineage
# ==== V229b end ====

BUNDLE_REPORT = _sys.modules['_tk_0c9293aeaac1_joint_v2'].PORTFOLIO_REPORT

def agent(observation, configuration=None):
    if int(observation['step']) < _var_0119:
        return _sys.modules['_gold_1ff5f6975590_hybrid_entry'].agent(observation, configuration)
    return _sys.modules['_tk_0c9293aeaac1_round_controller'].agent(observation, configuration)
